// Mod 2, first try: ANSWER. Hold a shell command that deletes a whole folder.
export function register(on) {
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (e.command.includes('rm -rf')) {
      // No next(e): the command never runs, and Claude reads this sentence instead
      return { deny: 'Held by the guard mod: this command deletes a whole folder. Ask the user first.' }
    }
    return next(e)
  })
}

